class Parse(HTMLParser):
 def __init__(self):super().__init__();self.urls=[];self.ids=set()
 def handle_starttag(self,tag,attrs):
  d=dict(attrs)
  if "id" in d:self.ids.add(d["id"])
  for k in ("href","src"):
   if k in d:self.urls.append(d[k])
